// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a mock token that reverts on transferFrom
        // We'll use a simple contract to simulate the revert
        // But the test must use the actual C contract with a real address that reverts
        // The simplest is to use the zero address, which will revert on call
        address from = address(0x1);
        address token = address(0x0); // zero address has no code, call will revert
        address[] memory tos = new address[](1);
        tos[0] = address(0x2);
        uint256 v = 100;

        bool ok;
        try c.transfer(from, token, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference reverts -> ok false; buggy does not revert -> ok true
        assertTrue(!ok);
    }
}

