pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address from = address(0x1);
        address caddress = address(0x2);
        address[] memory tos = new address[](1);
        tos[0] = address(0x3);
        uint v = 100;

        bool success;
        try c.transfer(from, caddress, tos, v) {
            success = true;
        } catch {
            success = false;
        }

        assertTrue(success);
    }
}
